import 'package:flutter/widgets.dart';

import 'ar_text.dart';
import 'sc_text.dart';

/// Set while a world in one fixed language is open (the Arabic course is always in Arabic).
String? m1LangOverride;

// Texts of the maths games (French, English, Arabic).

String m1Lang(BuildContext c) {
  if (m1LangOverride != null) return m1LangOverride!;
  final l = Localizations.localeOf(c).languageCode;
  if (l == 'zgh') return 'fr';
  return const ['fr', 'en', 'ar'].contains(l) ? l : 'en';
}

String m1T(BuildContext c, String key, [Map<String, Object>? args]) {
  final l = m1Lang(c);
  var s = _s[l]?[key] ?? scS[l]?[key] ?? (l == 'ar' ? arS[key] : null) ?? _s['fr']![key] ?? scS['fr']![key] ?? key;
  args?.forEach((k, v) => s = s.replaceAll('{$k}', '$v'));
  return s;
}

